fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    // Lengths for convenience
    let x_len = x.len();
    let y_len = y.len();

    // Construct the first matrix: each row is a copy of x
    let x_mat = (0..y_len)
        .map(|_| x.clone())
        .collect::<Vec<Vec<f32>>>();

    // Construct the second matrix: each row contains the corresponding y element repeated x_len times
    let y_mat = y.iter()
        .map(|&val| vec![val; x_len])
        .collect::<Vec<Vec<f32>>>();

    (x_mat, y_mat)
}